import{_ as t,a as o,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Export Invoices","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-invoices-export","title":"Export Invoices (CSV)","description":"Download the invoices datagrid as a CSV file — the same data the admin Invoices \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/invoices/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output invoices.csv\\n","response":"# Binary response: a text/csv attachment is written to invoices.csv\\n# (Content-Disposition: attachment; filename=\\"invoices.csv\\"). Sample contents:\\n\\nID,\\"Order ID\\",Status,\\"Grand Total\\",\\"Invoice Date\\"\\n587,2413,paid,$554.00,\\"2026-06-04 18:34:43\\"\\n"},{"id":"admin-invoices-export-xlsx","title":"Export Invoices (XLSX)","description":"Download the invoices datagrid as an XLSX file — the same data the admin Invoices \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/invoices/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output invoices.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"invoices.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-invoices-export-xls","title":"Export Invoices (XLS)","description":"Download the invoices datagrid as an XLS file — the same data the admin Invoices \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/invoices/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output invoices.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"invoices.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/invoices/export.md","filePath":"api/rest-api/admin/sales/invoices/export.md","lastUpdated":1786429091000}`),i={name:"api/rest-api/admin/sales/invoices/export.md"};function s(r,e,d,c,p,l){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="export-invoices" tabindex="-1">Export Invoices <a class="header-anchor" href="#export-invoices" aria-label="Permalink to &quot;Export Invoices&quot;">​</a></h1><p>Downloads the invoices datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Sales → Invoices</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON. Requires the <code>sales.invoices.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/invoices/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the five datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Invoice number.</td></tr><tr><td><code>Order ID</code></td><td>The parent order&#39;s number.</td></tr><tr><td><code>Status</code></td><td>The invoice state (e.g. <code>paid</code>, <code>pending</code>).</td></tr><tr><td><code>Grand Total</code></td><td>The invoice&#39;s total, in the store&#39;s base currency, formatted (e.g. <code>$554.00</code>).</td></tr><tr><td><code>Invoice Date</code></td><td>When the invoice was created.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>; any other value returns <code>422</code>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/invoices/list.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>id</code>, <code>order_id</code>, <code>state</code>, <code>base_grand_total_from</code> / <code>_to</code>, <code>created_at_from</code> / <code>_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.invoices.view</code></p>',12)]))}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
